var stars = [];
var starsNum = 800;

function setup() {
  createCanvas(500, 500);
  noStroke();

  for (var i = 0; i < starsNum; i++) {
    if (i < starsNum / 3) {
      starColor = "yellow";
    } else if (i < starsNum * 2 / 3) {
      starColor = "magenta";
    } else {
      starColor = "cyan";
    }
    stars.push(new Star(starColor));
  }
}

function draw() {
  blendMode(BLEND);
  background(0);

  blendMode(ADD);
  for (var i = 0; i < starsNum; i++) {
    stars[i].display();
  }
}

function Star(tmpColorName) {
  this.R = 150;
  this.x = this.R * randomGaussian();
  this.y = this.R * randomGaussian();
  this.r = random(3, 20) * 5;
  this.colorName = tmpColorName;
  this.theta = 0;

  switch (this.colorName) {
    case "cyan":
      this.color = color("#00ffff15");
      this.speed = 1;
      break;
    case "magenta":
      this.color = color("#ff00ff15");
      this.speed = 2;
      break;
    case "yellow":
      this.color = color("#ffff0015");
      this.speed = 0.25;
      break;
  }

  this.display = function() {

    fill(this.color);
    push();
    translate(width / 2, height / 2);
    rotate(radians(this.theta));
    ellipse(this.x, this.y, this.r, this.r);
    pop();


    this.theta += this.speed;
  }
}
